"""Test the public slugify behavior using only the standard library.

Responsibilities: exercise deterministic text normalization and input validation.
Assumptions: the contract is the one documented by slug.slugify; tests make no
service calls. AI-assisted test file; no copyright notice is asserted.
"""

import unittest

from slug import slugify


class SlugifyTests(unittest.TestCase):
    def test_ordinary_text_becomes_lowercase_hyphenated_slug(self):
        self.assertEqual(slugify("Hello World 42"), "hello-world-42")

    def test_punctuation_and_whitespace_runs_collapse_to_one_hyphen(self):
        self.assertEqual(slugify("  One---two,\tthree!!  "), "one-two-three")

    def test_unicode_accents_decompose_and_non_ascii_characters_are_omitted(self):
        self.assertEqual(slugify("Café 東京 déjà-vu"), "cafe-deja-vu")

    def test_empty_or_non_ascii_only_input_returns_empty_string(self):
        self.assertEqual(slugify(""), "")
        self.assertEqual(slugify("東京🙂"), "")
        self.assertEqual(slugify("...   !!!"), "")

    def test_non_string_input_raises_type_error(self):
        for value in (None, 42, b"hello"):
            with self.subTest(value=value):
                with self.assertRaises(TypeError):
                    slugify(value)


if __name__ == "__main__":
    unittest.main()

